mapper.select:
WITH candidates AS (
SELECT #{item.questionNo} AS question_no, CONVERT(#{item.questionText} USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AS question_text
) SELECT candidate.question_no FROM candidates candidate WHERE EXISTS ( SELECT 1 FROM t_question existing WHERE existing.version_id = #{versionId} AND existing.deleted = 0 AND existing.question_text = candidate.question_text ) OR EXISTS ( SELECT 1 FROM candidates earlier WHERE earlier.question_no < candidate.question_no AND earlier.question_text = candidate.question_text )
